    disc=r2(sub*TIER.get(customer.get('tier'),Decimal(0)))
    tax=r2((sub-disc)*TAX)
    tot=sub-disc+tax
    return {'subtotal':str(r2(sub)),'discount':str(disc),'tax':str(tax),'total':str(r2(tot))}

def format_money(x):
    return str(r2(Decimal(str(x))))
